    /// <summary>
    /// MPJ_3972_SAPPredictor - kscerri - 09/07/2021
    /// Caption visible according to FSD 5046
    /// </summary>
    protected void new()
    {
        super();

        this.parmDialogCaption("@MET:SAPPredictor");
    }

/// <summary>
/// MPJ_3972_SAPPredictor - kscerri - 09/07/2021
/// Automatically populates the batch text required by user before submitting to batch
/// </summary>
/// <returns>caption</returns>
public ClassDescription caption()
{
    return "@MET:SAPPredictor";
}

    /// <summary>
    /// MPJ_3972_SAPPredictor - kscerri - 09/07/2021
    /// Main method required to run the opration
    /// </summary>
    /// <param name = "args">Args</param>
    public static void main(Args args)
    {
        METSAPPredictorController controller;

        controller = new METSAPPredictorController();
        controller.initializeFromArgs(args);
        controller.startOperation();        
    }

/// <summary>
/// MPJ_3972_SAPPredictor - kscerri - 09/07/2021
/// BP to have a constructor for new controller.
/// </summary>
/// <returns>Controller instance</returns>
public static METSAPPredictorController construct()
{
    return new METSAPPredictorController();
}
